(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-streaming-codec-chunk"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-1\">一 · 事故现场：整段编解码在流式对话里为何必然崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-2\">二 · 它到底切开了什么：感受野的块化与状态延续</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-3\">三 · 代价落在哪里：状态缓存的复杂度与显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-4\">四 · 它不解决什么：三条清晰的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-5\">五 · 一个具体例子：20ms 块上的状态对齐失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-6\">六 · 适用边界的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-7\">七 · 分块推理解决的是“首包等不起”，不是“音质不够好”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-8\">八 · 请求到达与帧块产出：从连续流到可调度单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-9\">九 · 编码器逐块前向：读取状态、输出 token</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-10\">十 · token 流送入解码器：复用状态、立即出波形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-11\">十一 · 播放缓冲与状态更新：延迟账本的最后一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-12\">十二 · 状态对齐检查与重同步：失败模式的拦截点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-13\">十三 · 单块流水线的代价分解与块长取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-14\">十四 · 块边界的状态契约：失效条件与常数级代价的来处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-15\">十五 · 首包延迟公式的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-16\">十六 · 状态递推式与感受野约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-17\">十七 · 块边界对齐：重叠-相加与重同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-18\">十八 · 块长 B 的优化目标与夹逼</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-19\">十九 · 伪代码：状态机与关键路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-20\">二十 · 状态延续的边界条件与失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-21\">二十一 · 请求形态：谁在喂块，块从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-22\">二十二 · 长度分布：块数多不等于负载重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-23\">二十三 · 并发与批大小：小批拼接的隔离前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-24\">二十四 · 负载不对时：三种可诊断的失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-25\">二十五 · 配方落地：把 SLO 翻译成块参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-26\">二十六 · 负载配方与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-27\">二十七 · 硬件档位：按块长与并发数反推算力与带宽需求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-28\">二十八 · 并行拓扑：单流单块为主，多流按块拼接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-29\">二十九 · 量化方案：计算路径低精度，状态缓存高精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-30\">三十 · KV 策略：卷积状态与量化器历史的容量模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-31\">三十一 · 调度参数：块长、批窗口与缓冲深度的联合整定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-32\">三十二 · 可复现的配置思路：从 SLO 倒推，按约束收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-33\">三十三 · 显存账：为什么分块后峰值与时长解耦，却与层数线性绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-34\">三十四 · 带宽账：块太小先把 L2 与 HBM 的有效带宽打下来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-35\">三十五 · 通信账：多流与多卡时，状态同步比 token 同步更贵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-36\">三十六 · 功耗与利用率：低批小块是最差的能效区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-37\">三十七 · 尾延迟：规模上去以后，先崩的是拼批等待与状态重同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-38\">三十八 · 规模上限的判定顺序与一个具体例子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-39\">三十九 · 规模上去以后，先崩的是状态缓存与块边界，不是显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-40\">四十 · 精度漂移：状态缓存是唯一不能降精度的东西</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-41\">四十一 · OOM 的三个来源与隔离手法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-42\">四十二 · 批抖动与路由不均：小批多流的调度病理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-43\">四十三 · 尾延迟尖刺：状态重同步是尖刺的主要制造者</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-44\">四十四 · 监控面与回滚阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-45\">四十五 · 块边界与状态缓存：分块推理的失效面与可回滚监控</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-46\">四十六 · 同族谱系：四种流式解码的切分维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-47\">四十七 · 决策表：按负载形态落到具体算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-48\">四十八 · 适用条件：块长 B 与感受野 R 的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-49\">四十九 · 与层轴、token 轴算法的组合与排斥</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-50\">五十 · 选型的工程判断：三个可测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-codec-chunk-sec-51\">五十一 · 块切分与状态延续的决策边界：何时该用分块、何时退回整段或 RVQ 层间流式</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:593px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 592.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达：文本/声学模型按帧块（如 20ms）产出连续隐表示或波形块</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">编码器按块前向，读取上一块保留的卷积状态与量化器历史，输出当前块离散 to…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">token 流送入解码器，解码器同样按块前向并复用上块状态，立即输出波形块</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">波形块进入播放缓冲，同时更新跨块状态缓存（卷积 padding、归一化统计）</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">若块间状态未对齐则触发重叠-相加或状态重同步，保证拼接无爆音</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-streaming-codec-chunk-sec-1\">一 · 事故现场：整段编解码在流式对话里为何必然崩</h3>\n<p>先看一个不涉及任何实验数字、但结构上必然发生的线上事故形态。某语音对话服务把神经音频编解码器（SoundStream/AudioDec 一类）按最自然的方式接入：声学模型产出完整一句话的隐表示，攒齐后一次性送进编码器得到离散 token，再一次送进解码器还原波形，最后交给播放端。离线评测里音质无可指摘，一上实时链路就出问题——用户说完话后要等整段音频走完一次前向才能听到第一个音节，而这段等待随语句长度线性增长。更糟的是显存：整段前向要求全部帧同时驻留在感受野内，中间激活与量化器查表的中间缓冲随音频长度膨胀，多流并发时峰值叠加，直接把单卡推到 OOM 边缘，触发重试与降级，形成“越忙越慢、越慢越积压”的正反馈。</p>\n<p>这不是调参能救的问题，而是算法形态与 SLO 形态不匹配。整段编解码的延迟结构是 $$L_{\\text{first}} = t_{\\text{enc}}(T) + t_{\\text{dec}}(T) + t_{\\text{buf}}$$，其中 T 是整句总时长，两项前向都随 T 增长。而流式对话要求的是 $$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$，首包只依赖一个块。两条式子的差别不在常数因子，而在自变量：一个是总时长，一个是块长。只要业务是“边说边出音”，前者在结构上就不可能达标。分块推理要解决的正是这个自变量替换问题：把 O(T) 的首包与显存峰值压成 O(B)。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-2\">二 · 它到底切开了什么：感受野的块化与状态延续</h3>\n<p>分块推理的机制核心不是“把音频切成小段分别跑”，那样拼接处会因感受野截断而产生能量跳变。真正的做法是按固定帧块切分编解码器卷积/Transformer 的感受野，并维护跨块因果状态缓存，使每一块的前向在数学上等价于整段前向在该块上的输出。形式化地，设块长 B、感受野 R，第 t 块输出依赖上一块缓存的状态 $$s_{t-1}$$ 与当前块输入 $$x_t$$：</p>\n<div class=\"formula\">$$y_t = f(x_t, s_{t-1}),\\quad s_t = g(x_t, s_{t-1})$$</div>\n<p>状态 $$s$$ 的具体内容是卷积 padding 的尾部样本、归一化层的滑动统计量、量化器历史（前一块的残差与码本索引上下文）。只要块边界处的重叠量足以覆盖感受野，即 $$B \\ge R$$ 的边界重叠足够，拼接处就没有感受野截断，输出与整段前向逐样本一致。这条等价性是整个算法成立的根基：它不是近似，而是把一次长前向重排成若干次短前向加状态传递。</p>\n<p>按数据流顺序走一遍：文本/声学模型按帧块（如 20ms）产出连续隐表示或波形块；编码器逐块前向，读取上一块保留的卷积状态与量化器历史，输出当前块离散 token；token 流送入解码器，解码器复用上块状态逐块前向并立即输出波形块；波形块进入播放缓冲，同时更新跨块状态缓存。注意编码与解码是串接在同一条块流水上的，首包延迟因此约等于一个块的前向时间加播放缓冲填充时间，而不是两段完整前向之和——这是分块相对整段的第二个结构性收益。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-3\">三 · 代价落在哪里：状态缓存的复杂度与显存账</h3>\n<p>收益不是白来的。跨块状态缓存把“无状态的一次前向”变成了“有状态的流水线”，实现复杂度随层数与块长上升。每一层卷积都要正确保存 padding 尾部，每一个归一化层都要延续统计量，量化器要保留历史上下文；任何一处漏存或错位，都会在块边界产生周期性伪影。显存账则相对干净：峰值仅与块大小和状态缓存有关，长音频不随总时长增长。KV 概念上对应卷积状态与量化器历史缓冲，容量与块长和层数成正比。这带来一个反直觉的工程判断——分块推理的显存瓶颈从“音频有多长”变成了“模型有多深、块有多大”，容量规划的对象彻底换了。</p>\n<p>代价的另一面是块长 B 的取舍。B 太小，GPU 利用率下降，单块前向的固定开销（kernel launch、状态读写）摊不薄，且编解码器感受野无法覆盖有效上下文，音质与吞吐同时恶化；B 太大，首包延迟回升，直接顶到 SLO 上限。可用区间被两侧夹住：下限受感受野与 GPU 利用率约束，上限受首包 SLO 约束，典型取 20–40ms。这个区间窄得没有多少腾挪空间，所以块长不是可以随手调的旋钮，而是由 SLO 与模型感受野共同钉死的设计参数。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>整段编解码</th><th>分块 + 状态缓存</th></tr></thead><tbody><tr><td>首包延迟</td><td>随总时长 T 线性增长</td><td>约一个块的前向时间加缓冲填充</td></tr><tr><td>显存峰值</td><td>随音频长度膨胀</td><td>仅与块长、层数、状态缓存有关</td></tr><tr><td>实现复杂度</td><td>低，一次前向</td><td>高，需逐层状态延续与重同步</td></tr><tr><td>主要失败模式</td><td>OOM、首包超时</td><td>块边界伪影、状态错位、流间污染</td></tr></tbody></table>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-4\">四 · 它不解决什么：三条清晰的边界</h3>\n<p>第一条边界是 RVQ 层间查表带宽。分块推理聚焦卷积/Transformer 感受野的块切分与状态延续，它不改变残差矢量量化逐层查表的访存模式；层间查表带宽的优化是另一条算法线的事，本算法既不触碰也不受益。把块切分当成 RVQ 带宽问题的解法，是把两个正交的瓶颈混为一谈。</p>\n<p>第二条边界是模型本身的因果性。分块等价于整段前向的前提是编解码器在时间上因果、状态可延续。若模型含非因果卷积或全局注意力，块边界处的未来上下文无法由有限状态承载，等价性破裂，只能退化为重叠-相加的近似拼接，音质与延迟的权衡立刻变差。这是适用性的硬门槛，不是工程技巧能绕过的。</p>\n<p>第三条边界是块内并行度。分块把长序列拆成短块，单块内部的并行规模随之缩小；它换来的是常数级首包与显存，代价是单流前向的 GPU 占用率偏低。多流并发时按块拼接小批可以部分找回利用率，但这属于批调度层面的补偿，不是分块算法自身的收益。此外，超长流需定期状态重同步以防漂移——状态缓存的数值误差会随块数累积，重同步是必要的维护动作而非可选优化。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-5\">五 · 一个具体例子：20ms 块上的状态对齐失败</h3>\n<p>设想一条实时 TTS 链路，块长取 20ms，编码器为多层因果卷积，解码器复用上块状态。上线后用户反馈“每 20ms 一次的轻微咔哒”。排查路径很直接：把块边界处的输出与整段前向的对应片段逐样本比对，若差异集中在边界若干样本上，且能量出现周期性跳变，则几乎可以断定是跨块状态未正确延续——最常见的是卷积 padding 尾部少存了一个样本，或归一化统计量在块间被重置。修复不是调块长，而是补齐状态传递：确保第 t 块读取的 $$s_{t-1}$$ 与第 t-1 块写出的 $$s_{t-1}$$ 逐字段一致，并在边界做重叠-相加或状态重同步。这个例子的工程含义是，分块推理的调试对象从“模型输出对不对”变成了“状态在块间是否守恒”，验证手段也相应从端到端听感转为边界逐样本比对。</p>\n<p>同一例子还能暴露多流并发的隐患：若各流的状态缓存未隔离，或重同步时机不一致，按块拼接的小批会把 A 流的卷积尾部喂给 B 流，表现为流间串音与状态污染。这类故障在单流测试里完全不可见，只在并发下出现，因此状态隔离必须作为批拼接的前置约束写进实现，而不是事后补丁。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-6\">六 · 适用边界的工程判据</h3>\n<p>把适用性收敛成可执行的判据：当业务的首包 SLO 以百毫秒计、音频以流式方式持续产出、且编解码器在时间上因果可状态化时，分块推理是正确形态；当业务是离线批量转码、对首包无要求时，整段前向的实现复杂度更低，分块反而引入不必要的状态维护成本。块长的选择由两侧约束夹出：下限是感受野覆盖与 GPU 利用率，上限是首包 SLO，落在 20–40ms。部署上，单卡推理 GPU（含 Blackwell 档）以单流单块前向为主，多流时按块做小批拼接；量化可对编码器/解码器卷积与量化器查表做低精度，但状态缓存必须保持高精度——跨块误差会随块数累积，低精度状态是伪影的温床。这条“计算可低精度、状态须高精度”的分界，是分块推理在数值层面最值得记住的一条工程判断。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-7\">七 · 分块推理解决的是“首包等不起”，不是“音质不够好”</h3>\n<p>先说一个线上事故的形态：实时语音对话链路里，TTS 侧把整句文本交给声学模型后一次性产出完整波形，再整段送入神经音频编解码器（SoundStream/AudioDec 一类）做编码与解码。文本侧其实早已逐帧吐出了隐表示，但编解码器要等全部帧进入感受野才给出第一个输出，于是首包延迟随回复长度线性增长——用户说完话后听到的第一个音节被拖到整段合成结束之后。与此同时，整段前向的显存峰值随音频长度膨胀，长回复把激活与中间特征全部压在显存里，与同卡上的并发流争抢容量，触发抢占与重调度，表现为“短回复正常、长回复必卡”的锯齿状 SLO 违约。这类事故的根因不是模型质量，而是执行粒度：编解码器被当成一个整段算子调用，而链路其余部分都是流式的。</p>\n<p>分块推理正是针对这个粒度错配。它把卷积/Transformer 的感受野按固定帧块切分，维护跨块因果状态缓存，逐块编码与解码，使首包只依赖当前块与有限历史状态：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</div>\n<p>代价从 O(T) 降为 O(B)，B 取 20–40ms 即可满足实时对话的首包预算。但必须讲清它不解决什么：它不提升编解码器的率失真性能，不减少 RVQ 层间查表带宽（那是残差矢量量化流式解码的主题），也不替代声学模型的帧级调度；它只把“整段一次性前向”换成“定长块 + 状态延续”。因此当链路瓶颈在声码器声学建模、在文本侧首 token 延迟、或在网络回传时，分块编解码器带来的收益会被上游掩盖，此时应先修上游而不是调块长。</p>\n<p>边界由两个方向夹住。块长下限受感受野与 GPU 利用率约束：块太小，单块前向的 kernel 启动与状态读写开销占比上升，SM 占用率下降，吞吐恶化，且感受野无法覆盖有效上下文，音质同步下滑；块长上限受首包 SLO 约束，B 越大首包越接近整段行为。状态缓存是这套方案真正的工程负担：设块长 B、感受野 R，第 t 块输出依赖上一块缓存状态，$$y_t = f(x_t, s_{t-1}),\\ s_t = g(x_t, s_{t-1})$$，只有边界重叠量足够（$$B \\ge R$$ 的重叠部分）拼接处才无感受野截断。卷积 padding 与归一化统计未正确延续时，块边界出现周期性爆音与能量跳变，听感上是每块一次的咔哒声；多流小批拼接时若各流状态缓存未隔离或重同步时机不一致，则出现流间串音与状态污染。量化可以压低编码器/解码器卷积与量化器查表的精度以省带宽，但状态缓存必须保持高精度，否则跨块误差会逐块累积成漂移，超长流还需定期状态重同步。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>工程处置</th></tr></thead><tbody><tr><td>状态缓存未延续 padding/归一化统计</td><td>块边界周期性爆音、能量跳变</td><td>重叠-相加或状态重同步</td></tr><tr><td>块长过小</td><td>GPU 利用率与感受野有效性双降</td><td>以 20–40ms 为下界锚点</td></tr><tr><td>多流状态未隔离</td><td>流间串音、状态污染</td><td>按流独立缓存、统一重同步时机</td></tr></tbody></table>\n<h3 id=\"alg-streaming-codec-chunk-sec-8\">八 · 请求到达与帧块产出：从连续流到可调度单元</h3>\n<p>流式编解码器分块推理的第一步不是卷积，而是把一条连续音频流切成推理系统能够调度的离散单元。上游文本/声学模型（或对话系统中的 TTS 前端）按固定帧块产出隐表示或波形块，块长 B 取 20–40ms。这一步的输入是请求标识、采样率、声道数与当前块序号；输出是一个形状为 <code>[1, C, B·f_s]</code> 的波形块或 <code>[1, D, B]</code> 的隐表示块，附带该请求的块内时间戳。代价不在算力而在调度：块到达节奏由上游模型的自回归步进决定，若上游出块抖动，下游编码器就会出现空转或排队。工程上要把“块到达”做成带水位线的队列——队列深度超过一个块就触发背压，低于半个块就允许上游继续，避免为追求低延迟而把批大小压到 1 导致 GPU 利用率塌陷。一个具体例子：实时对话中每 20ms 到达一块，若编码器单块前向耗时 6ms，则队列在稳态下只保留 1–2 个块，首包延迟由“块到达 + 前向 + 缓冲填充”三段构成，而不是整段音频的编码时间。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-9\">九 · 编码器逐块前向：读取状态、输出 token</h3>\n<p>编码器按块前向，输入是当前块 <code>x_t</code> 与上一块保留的卷积状态 <code>s_{t-1}</code>（padding 尾巴、归一化滑动统计、量化器历史），输出当前块的离散 token 序列。机制上，卷积层的因果 padding 不能每块重新零填充，否则块边界处感受野被截断；正确做法是把上一块末尾 R−1 个采样（R 为感受野）作为本块的左侧上下文拼进来，前向后再把本块末尾的 R−1 个采样写回状态缓存。形式化为：</p>\n<div class=\"formula\">$$y_t = f(x_t, s_{t-1}),\\quad s_t = g(x_t, s_{t-1})$$</div>\n<p>其中 <code>g</code> 只做状态滚动，不引入额外前向。量化器一侧同样有历史：残差矢量量化的层间查表若跨块复用码本索引，需把上一块的量化残差与层指针带入，否则块边界码字跳变会产生能量台阶。代价体现在两处：显存上状态缓存与层数、块长成正比而不随总时长增长，这是分块推理相对整段前向的核心收益；带宽上每块要读写一次状态缓存，块越小状态读写占总带宽比例越高。举例：一个 8 层卷积编码器、块长 20ms、状态缓存约数十 KB 量级，单块前向在 Blackwell 单卡上属于小 kernel 主导，kernel launch 开销可能超过计算本身，因此要把编码器与量化器查表融合进少数几个 kernel，减少每块的启动次数。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-10\">十 · token 流送入解码器：复用状态、立即出波形</h3>\n<p>编码器输出的 token 流不等待整句结束，而是逐块送入解码器。解码器的输入是当前块 token 与它自己的上块状态（转置卷积的尾部、激活归一化统计），输出是当前块波形。关键机制是解码器的状态必须与编码器块边界严格对齐：编码器在块尾写入的状态，解码器必须在同一时间偏移上读取，二者共享同一个块时钟。若解码器使用转置卷积，块边界处会出现重叠区，需做重叠-相加（overlap-add）把相邻块在重叠窗内加权合并，窗函数通常取升余弦，保证拼接处一阶连续。代价是解码器每块前向的算力通常高于编码器（波形重建的采样率高），单块解码耗时决定首包延迟的下限；同时重叠-相加需要保留上一块尾部波形，增加一份与重叠长度成正比的缓冲。具体例子：20ms 块、重叠 5ms 时，解码器每块实际计算 25ms 的波形再裁掉重叠段，多出的 25% 算力换的是无爆音拼接，这笔账在 SLO 以首包延迟为主指标时必须算清。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-11\">十一 · 播放缓冲与状态更新：延迟账本的最后一段</h3>\n<p>波形块进入播放缓冲，同时更新跨块状态缓存。这一步的输入是解码器输出的波形块与当前状态，输出是写入环形缓冲的 PCM 段和滚动后的新状态。首包延迟由此闭合：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</div>\n<p>其中 <code>t_buf</code> 是播放缓冲填充到可播水位的时间，工程上取一个块到一个半块，用来吸收上游抖动。状态更新必须与播放解耦：状态滚动在 GPU 侧完成，播放缓冲在主机侧或音频设备侧消费，二者用事件同步而非轮询，否则每块的同步开销会吃掉小块的延迟收益。代价是缓冲水位直接叠加在首包延迟上，水位越高越稳但越慢；多流并发时每条流要有独立的环形缓冲与独立状态缓存，不能共享，否则流间串音。一个具体判断：当 <code>t_enc + t_dec</code> 已接近块长 B 时，再减小 B 只会让 GPU 利用率下降而首包延迟不再改善，此时应把预算花在 kernel 融合与状态缓存布局上，而不是继续切小块。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-12\">十二 · 状态对齐检查与重同步：失败模式的拦截点</h3>\n<p>每块前向后要做一次轻量的一致性检查：比较本块起始处由状态缓存重建的上下文与上一块实际尾部是否在容差内一致，归一化统计的均值/方差是否连续。若不一致则触发重叠-相加或状态重同步——丢弃错位状态，用当前块前若干帧重新预热感受野。这一步的输入是状态缓存与块边界采样，输出是“继续”或“重同步”信号。代价是重同步本身要额外前向一个预热块，属于偶发但不可忽略的尾延迟尖峰；检查若做得太重（例如每块全量比对）会引入主机-设备往返，反而拖慢稳态。失败模式的典型形态是周期性爆音：卷积 padding 未延续导致每块边界感受野截断，听感上是每块一次的咔哒声；多流小批拼接时若各流状态缓存未隔离或重同步时机不一致，会出现流间状态污染。工程判断是：状态缓存保持高精度（不随量化一起降位），量化只作用于卷积权重与量化器查表，因为跨块误差会沿状态链累积，而权重误差不会。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-13\">十三 · 单块流水线的代价分解与块长取舍</h3>\n<p>把上述步骤串成一条流水线后，每块的代价可以按资源拆开看：编码器与解码器前向是算力与 kernel launch 开销，状态缓存读写是显存带宽，播放缓冲与同步是主机侧延迟，重同步是尾延迟。块长 B 是唯一同时牵动四者的旋钮。B 太小，单块算力不足以填满 SM，感受野覆盖的有效上下文变短，音质与吞吐同时恶化；B 太大，首包延迟按 B 线性回升，违背流式初衷。典型取值 20–40ms 正是在“一个块的前向时间加缓冲填充”能落进对话可接受首包窗口、且单块 kernel 尚能维持合理利用率的交集里。表格给出各步骤的输入输出与主要代价：</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>帧块产出</td><td>请求、块序号</td><td>波形/隐表示块</td><td>调度抖动、队列水位</td></tr><tr><td>编码器前向</td><td>块 + 上块状态</td><td>离散 token</td><td>kernel launch、状态读写带宽</td></tr><tr><td>解码器前向</td><td>token + 上块状态</td><td>波形块</td><td>算力（采样率高）、重叠区额外计算</td></tr><tr><td>缓冲与状态更新</td><td>波形块、状态</td><td>PCM 段、新状态</td><td>缓冲水位叠加延迟、同步开销</td></tr><tr><td>对齐检查/重同步</td><td>状态、边界采样</td><td>继续/重同步信号</td><td>偶发预热前向、主机往返</td></tr></tbody></table>\n<p>落到工程判断上：单流低延迟场景批大小为 1，多流时按块做小批拼接以摊薄 kernel launch，但拼接的前提是各流状态缓存物理隔离且块时钟对齐；量化沿编码器/解码器卷积与量化器查表推进，状态缓存保持高精度；长音频下显存峰值只与块大小和状态缓存有关，但状态缓存实现复杂度随层数与块长上升，超长流需定期状态重同步以防漂移。真正决定这条流水线能否守住 SLO 的，不是某一步的峰值算力，而是块边界上状态延续的正确性与每块同步开销是否被压到块前向时间之下。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-14\">十四 · 块边界的状态契约：失效条件与常数级代价的来处</h3>\n<p>分块推理把首包延迟压到 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</span> 的前提，是每一块的前向都严格满足 <span class=\"formula\">$$y_t = f(x_t, s_{t-1}),\\ s_t = g(x_t, s_{t-1})$$</span>。这里的 <span class=\"formula\">$$s_t$$</span> 不是抽象句柄，而是两份具体缓冲：卷积层的尾部 padding 样本（对因果卷积即左侧历史抽头），以及归一化层的滑动统计量（均值/方差或量化器查表所用的历史尺度）。失效几乎全部发生在这份契约被打破的时刻——状态缓存写入时机早于或晚于块前向完成、多流小批拼接时各流的 <span class=\"formula\">$$s_{t-1}$$</span> 被错误地跨流共享、或低精度量化只作用于卷积权重却把状态缓存也一并降精度，都会让第 t 块的第一帧与第 t-1 块的最后一帧在感受野上断开。听感上的表现是周期性的：每块一次咔哒声与能量跳变，周期恰为 B。工程上判断是否发生状态错位，不必听音频，直接比对相邻块边界处解码器输出的短时能量差与相位连续性即可，代价只是一次块级归约。</p>\n<p>块长 B 是这套方案唯一的自由变量，也是它全部代价的缩放因子。B 的下限由感受野 R 与 GPU 利用率共同锁定：若 <span class=\"formula\">$$B &lt; R$$</span>，单块前向无法覆盖编解码器卷积核的有效上下文，边界重叠量不足，必须靠重叠-相加补偿，而重叠区被重复计算，算力利用率随 B 缩小而线性恶化；同时 20ms 级的块在 Blackwell 单卡上难以填满 SM，单流批大小为 1 时 kernel 启动与同步开销占比上升，吞吐被摊薄。B 的上限则由首包 SLO 反向锁定：首包延迟约等于一个块的前向时间加播放缓冲填充时间，B 取到 40ms 以上时，缓冲填充本身已吃掉可感知的对话响应预算。因此 20–40ms 不是调参偏好，而是感受野下限与 SLO 上限夹出的可行区间。</p>\n<p>显存与带宽的账要分开算。显存峰值只与块大小和状态缓存有关：状态缓存容量正比于层数与块长，与总时长无关，这是相对整段前向最本质的收益——长音频不再让激活峰值随 T 膨胀。但带宽侧的代价并不消失：每块都要把 <span class=\"formula\">$$s_{t-1}$$</span> 读入、把 <span class=\"formula\">$$s_t$$</span> 写回，块越小，单位音频时长对应的状态读写次数越多，状态缓存的搬运量按 1/B 放大；量化器历史缓冲若保持高精度以避免跨块误差累积，这部分带宽无法靠低精度压缩。多流并发时按块拼小批能摊薄权重读取，但各流状态必须物理隔离——按流维拼接状态缓存、重同步时机逐流独立判定，否则串音与状态污染会以流间干扰的形式出现，且难以从单流指标上定位。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>状态缓存未延续 padding/统计量</td><td>块边界感受野截断</td><td>周期性爆音，需重叠-相加补救，算力重复</td></tr><tr><td>B 小于感受野 R</td><td>上下文覆盖不足</td><td>GPU 利用率与音质同时下降</td></tr><tr><td>状态缓存降精度</td><td>跨块误差累积</td><td>长流漂移，需定期重同步</td></tr><tr><td>多流状态未隔离</td><td>小批拼接共享缓冲</td><td>流间串音，定位困难</td></tr></tbody></table>\n<p>超长流的漂移是另一类边界：即便每块都正确延续状态，低精度卷积与量化器查表带来的微小误差会在状态缓存中逐块累积，表现为音色缓慢偏移而非突发爆音。对策是定期状态重同步——在句间静音或语义边界处用一小段重叠窗口重新对齐状态，把漂移截断在有界区间内。这一步的代价是一次额外的重叠前向，频率取决于精度档位与流时长，属于用少量算力换稳定性的工程判断，而非算法必需。</p>\n<h3 id=\"alg-streaming-codec-chunk-sec-15\">十五 · 首包延迟公式的逐项拆解</h3>\n<p>流式编解码器分块推理的性能上界由一条极简公式钉死：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</div>\n<p>三项各自对应一段真实的数据通路，不能合并看待。<span>t<sub>enc</sub>(B)</span> 是编码器对单个块的前向时间，输入是当前块 <span>x<sub>t</sub></span> 与上一块遗留的卷积状态 <span>s<sub>t−1</sub></span>；<span>t<sub>dec</sub>(B)</span> 是解码器对当前块 token 的前向时间，同样吃上一块状态；<span>t<sub>buf</sub></span> 是播放缓冲填充时间，即凑够一个可播放块所需的墙钟时间。关键推导一步在于：整段推理的延迟是 <span>O(T<sub>total</sub>)</span>，因为编码器必须等全部帧进入感受野才输出第一个 token；而分块后，第 t 块的输出只依赖 <span>x<sub>t</sub></span> 与 <span>s<sub>t−1</sub></span>，与 <span>T<sub>total</sub></span> 无关，故延迟塌缩为 <span>O(B)</span>。这一步不是近似，而是因果性假设的直接后果——只要状态缓存完整，历史长度就不再进入关键路径。</p>\n<p>工程上要盯住的是三项的相对权重。块长 B 取 20–40ms 时，<span>t<sub>enc</sub></span> 与 <span>t<sub>dec</sub></span> 都是单块前向，量级由层数、通道数与 GPU 利用率决定；<span>t<sub>buf</sub></span> 则近似等于块本身的时长，因为播放器必须攒满一块才能起播。这意味着首包延迟的下限被 <span>t<sub>buf</sub></span> 锁死：B 取 20ms，缓冲填充就至少贡献 20ms 量级的墙钟时间，编码解码再快也无法突破。反过来，把 B 压到 10ms 以下去追延迟，会让 <span>t<sub>enc</sub></span>、<span>t<sub>dec</sub></span> 中的固定开销（kernel launch、状态读写、量化器查表）占比飙升，GPU 利用率塌陷，公式第一、二项反而变差。这就是 20–40ms 这个区间的由来：它是 <span>t<sub>buf</sub></span> 与固定开销之间的折中点，而非拍脑袋的经验值。</p>\n<p>一个具体例子：实时 TTS 场景下，声学模型每 20ms 吐出一个隐表示块，编码器随即前向产出该块 token，解码器复用上块状态立即合成波形块送入播放缓冲。首包延迟等于一个块的前向时间加 20ms 缓冲填充，与整段合成时“等全文生成完再编码”的秒级等待形成量级差异。显存侧同理：整段前向的激活峰值随 <span>T<sub>total</sub></span> 膨胀，分块后峰值只与 B 和状态缓存容量相关，长音频不推高显存。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-16\">十六 · 状态递推式与感受野约束</h3>\n<p>跨块状态缓存的形式化是这套算法的骨架。设块长 B、感受野 R，第 t 块输出与状态更新写作：</p>\n<div class=\"formula\">$$y_t = f(x_t, s_{t-1}),\\quad s_t = g(x_t, s_{t-1})$$</div>\n<p>推导的关键一步在感受野边界：卷积层在第 t 块的首帧需要看到第 t−1 块末尾的若干帧才能算对，这段“越界依赖”正是 <span>s<sub>t−1</sub></span> 必须携带的内容。若把状态缓存简化为“只存最后一帧”，当 <span>R &gt; B</span> 时首帧的感受野被截断，输出与整段推理不一致，边界处出现能量跳变。因此约束是 <span>B ≥ R</span> 的边界重叠量足够——更准确地说，缓存必须覆盖 <span>R − 1</span> 帧的历史，块长本身不必大于 R，但块间重叠或状态长度必须补齐这段缺口。这条不等式是选择 B 的硬下界：感受野越大的编解码器架构（深层卷积、带注意力的 Transformer 块），所需状态缓存越长，B 的下限被推高，与首包 SLO 的上界形成夹逼。</p>\n<p>状态递推的第二个细节是归一化统计。若编码器含跨帧归一化（如对通道做滑动统计），<span>s<sub>t</sub></span> 里必须带上运行均值与方差，否则每块独立归一化会在边界产生增益突变。这类统计量的递推不是简单拷贝，而是按块做增量更新，伪代码落到可实现层面大致是：</p>\n<ul>\n<li>对每个卷积层，保留末尾 <span>R−1</span> 帧的输入激活作为 padding 缓存，块前向时把它拼到当前块头部；</li>\n<li>对归一化层，保留运行均值/方差（或滑动窗口计数），块前向时先更新统计再归一化；</li>\n<li>对量化器，保留上一块的残差与码本指针历史，保证 RVQ 层间查表的连续性；</li>\n<li>状态缓存的精度保持高精度（FP32 或至少 FP16），不随编码器/解码器一道降到低比特，避免跨块误差累积。</li>\n</ul>\n<p>代价在这里显形：状态缓存容量与块长、层数成正比，与总时长无关——这是分块推理显存恒定的来源，但也是实现复杂度的来源。每层一份 padding 缓存、每层一份统计量，层数翻倍则缓存翻倍，且这些缓存的读写落在关键路径上，直接计入 <span>t<sub>enc</sub></span>。带宽侧，状态读写是每块固定开销，块越小则单位音频摊到的状态带宽越高，这是小块的隐性成本。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-17\">十七 · 块边界对齐：重叠-相加与重同步</h3>\n<p>状态递推在数学上保证连续性，但实现上块边界仍需显式对齐。两条路径：重叠-相加（overlap-add）与状态重同步。重叠-相加的做法是让相邻块在时域上重叠若干帧，解码器输出重叠区的两段波形后按窗函数加权求和，把拼接处的相位与幅度不连续抹平。其代价是重叠区的计算被重复一次，有效吞吐按重叠比例折损：若块长 20ms、重叠 5ms，则每块多算 25% 的帧，吞吐下降同比例。状态重同步则是另一条路：不重复计算，而是在检测到块间状态未对齐（如缓存被截断、统计量漂移）时，用当前块输入重新初始化状态，代价是重同步那一块的质量略降，但避免了周期性重叠开销。</p>\n<p>选择哪条路径取决于失败模式的形态。跨块状态缓存未正确延续卷积 padding 或归一化统计时，块边界出现周期性爆音与能量跳变，听感上是每块一次的咔哒声——这种规律性伪影用重叠-相加能压住，因为伪影恰好落在重叠窗内被平滑。而超长流下的缓慢漂移（统计量累积误差、量化器历史偏移）不是周期性而是渐进的，重叠-相加无能为力，必须定期状态重同步。工程判断是：短流、块边界伪影为主，用重叠-相加；长流、漂移为主，用定期重同步；两者可叠加，但重叠比例与重同步周期都要计入延迟预算——重同步块的前向时间可能高于常规块，因为要重建完整状态。</p>\n<p>多流并发把这个问题放大。按块拼接小批时，各流的状态缓存必须隔离，重同步时机必须独立。若把不同流的块拼进同一 batch 却共用一份状态缓冲，或让重同步在 batch 粒度统一触发，就会出现流间串音与状态污染：A 流的重同步把 B 流的历史冲掉，B 流边界立刻爆音。可实现的约束是状态缓存按流索引寻址、重同步按流独立调度，batch 只做前向拼接不做状态合并。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-18\">十八 · 块长 B 的优化目标与夹逼</h3>\n<p>块长不是自由参数，而是被两条边界夹住的决策变量。下界来自感受野与 GPU 利用率：B 太小，单块前向的固定开销（kernel launch、状态读写、量化器查表）摊不开，<span>t<sub>enc</sub></span>、<span>t<sub>dec</sub></span> 不随 B 线性下降反而被常数项主导，同时感受野无法覆盖有效上下文，音质恶化。上界来自首包 SLO：<span>t<sub>buf</sub></span> 近似等于 B，B 越大缓冲填充越久，首包延迟回升。把这两条写成目标函数，就是在给定 SLO 上限 <span>L<sub>SLO</sub></span> 下最小化每块前向时间：</p>\n<div class=\"formula\">$$\\min_B\\ \\frac{t_{\\text{enc}}(B)+t_{\\text{dec}}(B)}{B}\\quad \\text{s.t.}\\ B \\ge R,\\ B + t_{\\text{fwd}}(B) \\le L_{\\text{SLO}}$$</div>\n<p>目标函数是“单位音频的前向成本”，分母 B 越大摊得越薄；约束一是感受野，约束二是首包。典型可行域落在 20–40ms。这个区间的物理含义清晰：20ms 对应语音帧的常见粒度，也是缓冲填充可接受的下限；40ms 是首包 SLO 还能容忍的上限，再大则对话的响应感变差。取 20ms 时单位成本偏高但延迟最优，取 40ms 时吞吐更好但首包吃紧，中间取值按部署形态调——单流低延迟对话偏 20ms，小批多流偏 40ms。</p>\n<p>一个具体判断：若部署目标是实时对话且 SLO 以首包为主指标，B 取 20ms，批大小为 1，此时 GPU 利用率本就不高，块小的代价被“反正只有单流”抵消；若同一张卡要服务多路流，按块拼小批，B 取 30–40ms 把固定开销摊薄，代价是每路流的首包延迟各增加一个块时长。这里没有免费午餐：多流吞吐与单流首包在 B 上直接对冲，容量规划必须把这两者分开核算，不能用一个 B 同时满足两类 SLO。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-19\">十九 · 伪代码：状态机与关键路径</h3>\n<p>把上述机制落到可实现，核心是一个按块推进的状态机，而非一次性前向。伪代码思路如下（以单流为例，多流时外层再套流索引）：</p>\n<ul>\n<li>初始化：为每层分配 padding 缓存与归一化统计缓冲，量化器历史置零；</li>\n<li>循环取块：从上游拿到 <span>x<sub>t</sub></span>（隐表示或波形块），长度 B；</li>\n<li>编码：把 <span>s<sub>t−1</sub></span> 的 padding 拼到 <span>x<sub>t</sub></span> 头部，前向编码器，得 token 块与新的卷积状态；更新归一化统计；</li>\n<li>解码：token 块连同解码器侧 <span>s<sub>t−1</sub></span> 前向，得波形块 <span>y<sub>t</sub></span>；</li>\n<li>对齐：若启用重叠-相加，与上一块尾部按窗加权拼接；若检测到状态漂移，触发重同步重建状态；</li>\n<li>输出与更新：波形块入播放缓冲，<span>s<sub>t</sub></span> 写回缓存，进入下一块。</li>\n</ul>\n<p>关键路径是“编码前向 + 解码前向 + 缓冲填充”，状态读写虽在路径上但可与前向重叠（预取下一块所需状态）。可优化的点在于把状态更新与前向解耦：卷积 padding 缓存的写入不必等整块算完，可在层间流水；归一化统计的更新可延后一块，只要不进入当前块的关键路径。这类流水化不改变公式，但把 <span>t<sub>enc</sub></span>、<span>t<sub>dec</sub></span> 中的状态开销藏进计算阴影里，是工程上把公式第一、二项压到接近纯计算时间的常用手段。</p>\n<p>失败模式在伪代码层面有明确触发点：状态缓存未按层正确延续 padding，块边界出现每块一次的咔哒声；B 设得过小，GPU 利用率与感受野有效性同时下降，音质与吞吐双输；多流拼接时状态未隔离，流间串音。三者的检测手段不同——周期性伪影看边界能量差，利用率看单块前向的固定开销占比，串音看流间输出的相关性异常。伪代码里应把这三项做成可观测的计数器，而不是等听感出问题再回头查。</p>\n<p>最后落在工程判断上：这套算法的可实现性取决于状态缓存的正确性，而正确性取决于“每层每流一份、精度不降、按块增量更新”三条纪律。公式给出的是延迟与显存的上界，伪代码给出的是把上界兑现的路径；两者之间的差距，全部由状态缓存的实现质量决定。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-20\">二十 · 状态延续的边界条件与失效面</h3>\n<p>跨块状态缓存让分块推理成立，但它只在特定条件下等价于整段前向。把第 t 块输出写成 <span class=\"formula\">$$y_t = f(x_t, s_{t-1}),\\ s_t = g(x_t, s_{t-1})$$</span>，这个递推要成立，前提是 <span class=\"formula\">$$s_{t-1}$$</span> 已经包含了第 t 块感受野所需的全部历史。设块长 B、感受野 R，则必须满足边界重叠量 <span class=\"formula\">$$B \\ge R$$</span>；一旦 B 小于 R，第 t 块的首批输出帧就会读到未被缓存覆盖的上下文，拼接处出现感受野截断。工程上这表现为块边界周期性爆音——每块一次的咔哒声，本质是卷积 padding 或归一化统计未正确延续造成的能量跳变。因此 B 的下限不是由延迟预算单独决定，而是被感受野与 GPU 利用率共同钳住：块太小，单块前向的 kernel 启动与调度开销占比上升，SM 占用率下降，编解码器感受野也无法覆盖有效上下文，音质与吞吐同时恶化。</p>\n<p>状态缓存的代价必须计入显存与带宽预算。缓存容量与块长、层数成正比而与总时长无关，这是分块相对整段的核心优势；但每一块前向都要读写这份状态，跨块状态搬运的带宽随层数线性增长，在单流低延迟场景下会与权重读取争抢 HBM 带宽。量化策略上，编码器/解码器卷积与量化器查表可走低精度，状态缓存本身应保持高精度，否则跨块误差会逐块累积并在长流上漂移，最终触发重同步。多流并发时按块拼接小批，若各流状态缓存未隔离或重同步时机不一致，会出现流间串音与状态污染，这是批调度层面必须显式建模的约束。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>工程对策</th></tr></thead><tbody><tr><td>B &lt; R，重叠不足</td><td>块边界感受野截断、周期性咔哒声</td><td>提高 B 或增大边界重叠量</td></tr><tr><td>状态缓存低精度</td><td>跨块误差累积、长流漂移</td><td>状态保持高精度，定期重同步</td></tr><tr><td>多流状态未隔离</td><td>流间串音、状态污染</td><td>按流分配独立缓存槽位</td></tr></tbody></table>\n<p>首包延迟的推导落在 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\ B \\ll T_{\\text{total}}$$</span> 上，其中 <span class=\"formula\">$$t_{\\text{buf}}$$</span> 是播放缓冲填充时间，B 取 20–40ms 时首包只依赖当前块与有限历史状态，与总时长解耦。伪代码落到可实现层面，核心是状态句柄的显式传递：<code>for blk in stream: y = dec(enc(blk, st_e), st_d); st_e, st_d = update(……); play(y)</code>，状态句柄必须与块一一绑定并在异常时丢弃重建，否则重同步逻辑本身会成为新的伪影源。块长上限则由首包 SLO 反向约束，B 增大虽提升 GPU 利用率与感受野有效性，但首包延迟随之回升，延迟与质量的折中点就落在 20–40ms 这个区间内。</p>\n<h3 id=\"alg-streaming-codec-chunk-sec-21\">二十一 · 请求形态：谁在喂块，块从哪来</h3>\n<p>分块推理的负载配方首先由上游决定：块不是凭空产生的，而是文本/声学模型按帧块吐出的连续隐表示或波形块。这意味着请求形态被上游的产出节奏锁定——上游每 20ms 产出一块，编解码器就必须在一个块周期内完成编码、量化、解码三段前向，否则播放缓冲会被抽干。流式对话与实时 TTS 是两类典型形态：前者块与块之间夹着用户打断、回声消除与对话状态机，块流可能被随时截断或重排；后者块流是单向、匀速、可预测的，负载更规整。工程上要区分这两类，因为打断意味着状态缓存必须支持“丢弃当前块、从新起点重建状态”，而匀速流只需延续状态。请求形态还决定了块内并发的粒度：单流低延迟场景下批大小为 1，GPU 上只有一个块在飞；小批多流场景下，多个流的当前块被拼成一个小批同时前向，块边界对齐成为调度前提。</p>\n<p>把请求形态写成约束，首包延迟的构成就是：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</div>\n<p>其中 $$t_{\\text{buf}}$$ 是播放缓冲填充时间，通常取一到两个块的时长以吸收抖动。这个式子说明：首包延迟与总时长无关，只与块长 B 和单块前向时间有关。于是负载配方的第一问不是“能跑多快”，而是“上游能否稳定按 B 供块”。若上游是自回归声学模型，其自身解码节奏可能慢于 B，编解码器再快也只能空等——这时瓶颈不在编解码器，而在上游的块产出率，负载配方要把编解码器的块周期与上游对齐，而不是一味压小编解码器延迟。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-22\">二十二 · 长度分布：块数多不等于负载重</h3>\n<p>长度分布对分块推理的影响与整段推理完全不同。整段推理的代价随总时长 T 线性增长；分块推理的显存峰值只与块大小 B 和状态缓存规模有关，与 T 无关。因此长音频请求在显存维度上是“免费”的，代价转移到别处：块数 N = T/B 决定了状态缓存的更新次数与重同步次数。设层数 L、每层状态缓存元素数 C（卷积 padding、归一化统计、量化器历史缓冲），状态缓存总量约为 L·C，与 B 成正比而与 N 无关；但每块都要读写这份缓存，所以状态带宽代价随 N 线性增长。长请求的真实负载是“状态缓存的反复搬运”，而不是“显存不够”。</p>\n<p>长度分布还影响重同步策略。超长流若一直沿用同一份状态缓存，浮点误差与量化误差会沿块链累积，表现为缓慢的音色漂移或能量偏移；工程上按固定块数间隔做一次状态重同步（用当前块输入重新初始化状态，配合重叠-相加抹平接缝），把漂移截断在有限步内。短请求则相反：块数太少，重同步的开销占比高，且首包延迟里 $$t_{\\text{buf}}$$ 的固定成本摊不薄。负载配方要按长度分布分档：短请求优先压 $$t_{\\text{buf}}$$，长请求优先控重同步频率与状态带宽。</p>\n<table class=\"mini\"><thead><tr><th>长度档</th><th>主导代价</th><th>配方倾向</th></tr></thead><tbody><tr><td>短（数个块）</td><td>首包固定开销 $$t_{\\text{buf}}$$</td><td>缓冲取一块，块长取上限</td></tr><tr><td>中（数十块）</td><td>块周期稳定性</td><td>批大小 1，状态缓存高精度</td></tr><tr><td>长（数百块以上）</td><td>状态带宽与漂移</td><td>定期重同步，状态缓存分层精度</td></tr></tbody></table>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-23\">二十三 · 并发与批大小：小批拼接的隔离前提</h3>\n<p>并发维度上，分块推理的批大小通常为 1 或小批多流。批大小为 1 时 GPU 利用率低，但延迟可预测，适合单流对话；小批多流把多个流的当前块拼成一个小批，一次前向服务多条流，吞吐上升而单流延迟基本不变——前提是各流的块边界对齐。若各流块长不同或到达时刻错开，拼接就要等最慢的流，尾延迟被拉长。负载配方因此要求：多流并发时统一块长 B，并按固定节拍做块对齐调度，把“等块”变成“凑批”。</p>\n<p>小批拼接的致命风险是状态污染。每个流持有独立的卷积 padding、归一化统计与量化器历史；若批内张量拼接时把状态缓存按批维堆叠却未按流索引隔离，或重同步时机在批内不一致，就会出现流间串音——A 流的归一化统计被 B 流的块更新，听感上是两条语音互相渗入。工程判断是：状态缓存必须按流 ID 显式索引，批内每个槽位的状态生命周期独立管理，重同步以流为单位触发而非以批为单位触发。吞吐代价是状态缓存的读写从“一块一份”变成“一批 N 份”，状态带宽随并发数线性上升，这也是并发上限的真实约束之一，而非算力。</p>\n<p>批大小的选择还要看块内前向的算术强度。块长 B 越小，单块前向的矩阵规模越小，批大小为 1 时 GPU 的 SM 占用率下降，算力被浪费在启动开销上；把多个流拼成小批能把算术强度拉回来，但拼接本身引入对齐等待。负载配方在这里是一个明确的权衡：并发数 N 与块长 B 的乘积决定单次前向的有效工作量，配方要让这个乘积落在 GPU 能吃饱的区间，同时不让对齐等待吃掉首包 SLO。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-24\">二十四 · 负载不对时：三种可诊断的失效</h3>\n<p>负载配方错配不会以“报错”形式出现，而是以三种可听的失效出现。第一种是块边界周期性爆音：跨块状态缓存未正确延续卷积 padding 或归一化统计，拼接处出现每块一次的咔哒声与能量跳变。诊断方法是看块边界处的波形不连续度与能量差分，若周期性出现即锁定状态延续错误，而非模型质量。第二种是块长过小：为追求低延迟把 B 压到感受野以下，GPU 利用率下降且感受野无法覆盖有效上下文，音质与吞吐同时恶化——延迟指标好看，但输出已经不可用。第三种是多流串音：批内状态未隔离或重同步时机不一致，流间互相污染，表现为两条语音的统计特征互相渗透。</p>\n<p>这三种失效对应三条配方红线：B 不得小于感受野所需的最小重叠量；状态缓存必须按流隔离且精度高于量化后的权重；重同步必须以流为单位。反过来，块长过大则首包延迟回升，$$L_{\\text{first}}$$ 中的 $$t_{\\text{enc}}(B)+t_{\\text{dec}}(B)$$ 随 B 增长，SLO 被突破。所以 B 的可行区间被两侧夹住：下限由感受野与 GPU 利用率决定，上限由首包 SLO 决定，典型取值落在 20–40ms。负载配方的核心工作就是把请求形态、长度分布、并发数映射到这个区间内的一个具体 B 与批策略，而不是取一个全局默认值。</p>\n<p>还有一个容易被忽略的错配：把整段推理的批策略直接搬到分块推理。整段推理可以大批量摊薄权重读取，分块推理的批是“块批”，批内每个元素是不同流的同一时刻块，权重读取被摊薄的倍数受并发数限制；若并发数不足而强行增大批，只能靠拉长块长凑工作量，直接推高首包延迟。工程判断是：分块推理的批大小上限由并发流数决定，而非由显存余量决定，显存余量在这里不是约束，状态缓存的隔离与带宽才是。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-25\">二十五 · 配方落地：把 SLO 翻译成块参数</h3>\n<p>落地时，负载配方是一张从 SLO 反推参数的映射表。首包 SLO 给定后，先扣掉 $$t_{\\text{buf}}$$，剩余预算分给编码与解码两段前向，得到单块前向时间上限；再由单块前向时间与硬件档位反推可行的 B 区间；最后由并发流数与状态缓存带宽反推批大小上限。三步之间互相牵制：B 越小单块前向越快但利用率越低，批越大吞吐越高但对齐等待越长。配方不是求一个最优点，而是求一个在 SLO 内可稳定复现的工作点。</p>\n<p>稳定性技巧要写进配方而不是事后补丁：块边界做重叠-相加或状态重同步，保证拼接无爆音；状态未对齐时触发重同步而非静默沿用。量化策略也属于配方的一部分：编码器/解码器卷积与量化器查表可做低精度，状态缓存保持高精度以避免跨块误差累积——这是分块推理区别于整段推理的量化红线，因为整段推理的误差只累积一次，分块推理的误差沿块链累积 N 次。KV 概念上对应卷积状态与量化器历史缓冲，容量与块长和层数成正比，不随总时长增长，这条性质是分块推理在长音频上显存稳定的根基，也是负载配方敢把长请求与短请求混部的前提。</p>\n<p>最后一条工程判断：负载配方的验证不能只看平均首包延迟，要看块边界指标与流间隔离指标。平均延迟达标而块边界爆音的分块推理，在听感上仍是失败的；并发吞吐达标而流间串音的部署，在对话场景里会被用户立刻察觉。配方把 B、批大小、状态精度、重同步间隔四个旋钮绑在一起调，任何一个单独调优都会把代价推到另一个维度上。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-26\">二十六 · 负载配方与失效边界</h3>\n<p>这套分块方案并非通用加速器，它的收益完全建立在“请求本身是流式”的前提上。适配的请求形态很窄：实时语音对话、流式 TTS、边生成边播放的声学前端。此时块长取 20–40ms，批大小通常为 1（单流低延迟）或小批多流拼接，SLO 主指标是首包延迟而非吞吐。首包只依赖当前块与有限历史状态，故 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</span> 中三项都随 B 而非总时长 T 缩放——这正是它能满足对话级 SLO 的原因。反过来，若请求是离线批量转写、整段配音或长音频后处理，负载没有“边产边播”的约束，分块反而把一次大前向拆成多次小前向，GPU 利用率下降、kernel 启动与状态读写开销摊薄不掉，吞吐低于整段路径。</p>\n<p>长度分布决定状态缓存是否成为瓶颈。状态缓存容量与块长和层数成正比，不随总时长增长，因此短请求（数秒级）与超长流在显存峰值上表现相近；但超长流需定期状态重同步以防数值漂移，重同步点会引入一次额外延迟尖峰。并发维度上，多流按块拼小批可提升利用率，代价是各流状态缓存必须严格隔离、重同步时机一致，否则出现流间串音与状态污染——这是比单流伪影更难排查的失效。下表给出负载与方案匹配的粗判：</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>匹配度</th><th>主要代价</th></tr></thead><tbody><tr><td>流式对话 / 实时 TTS，B=20–40ms</td><td>适配</td><td>状态缓存实现复杂度</td></tr><tr><td>离线整段批量，长音频</td><td>不适配</td><td>吞吐低于整段前向</td></tr><tr><td>多流并发小批拼接</td><td>条件适配</td><td>状态隔离与重同步一致性</td></tr></tbody></table>\n<p>负载不对时的失效是可听的、可测的。跨块状态缓存未正确延续卷积 padding 或归一化统计，块边界出现周期性爆音与能量跳变，听感上是每块一次的咔哒声；块长压得过小追低延迟，GPU 利用率与感受野有效性同时下降，音质与吞吐一起恶化；块长放大则首包延迟回升，直接击穿 SLO。工程判断因此落在 B 的可行区间：下限由感受野 R 与利用率约束（需保证 <span class=\"formula\">$$B \\ge R$$</span> 的边界重叠量足够，拼接处才无感受野截断），上限由首包 SLO 约束，典型 20–40ms。量化上可对编码器/解码器卷积与量化器查表做低精度，但状态缓存须保持高精度，否则跨块误差累积会把边界伪影放大成系统性失真。</p>\n<h3 id=\"alg-streaming-codec-chunk-sec-27\">二十七 · 硬件档位：按块长与并发数反推算力与带宽需求</h3>\n<p>分块推理的硬件选型不能从“模型多大”出发，而要从“每块前向必须在多少毫秒内完成”出发。首包延迟由 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}}$$</span> 给出，其中 B 取 20–40ms，播放缓冲 <span class=\"formula\">$$t_{\\text{buf}}$$</span> 通常留一到两个块的余量。这意味着单块前向的预算被压缩到个位数毫秒级，硬件档位的选择标准是：在 B=20ms 的最坏情况下，编码器与解码器各一次前向能否在预算内跑完，并且留出状态缓存读写的余量。</p>\n<p>Blackwell 档位在这里的差异不在峰值算力，而在两个具体机制上。第一是 tcgen05 MMA 与 TMEM 的配合：编解码器的卷积层在 im2col 之后可以走张量核心，但块长 20ms 对应的序列极短，矩阵乘的 M 维往往只有几十行，此时 2-SM MMA 的收益取决于能否把多流的小批在 N 维上拼起来，而不是靠单流的形状撑满。第二是 NVFP4/FP8 的吞吐档：低精度路径让单块前向的算力占用下降，真正被释放的是寄存器与共享内存，从而允许更大的状态缓存常驻片上。</p>\n<p>工程判断上，单卡即可覆盖单流低延迟场景；当并发流数上升，硬件档位应按“块拼接后的等效批”重新评估，而不是按流数线性外推。具体例子：8 路 20ms 块拼接成一批送入编码器，等效批为 8，此时瓶颈从算力转向状态缓存的带宽——每路每层都要读写自己的卷积 padding 与归一化统计，这部分访存量与层数、块长成正比，与总时长无关，正是分块推理显存峰值恒定的来源。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-28\">二十八 · 并行拓扑：单流单块为主，多流按块拼接</h3>\n<p>拓扑的第一原则是：单流路径上不做张量并行。块长 20ms 的前向里，集合通信的固定开销会直接吃掉首包预算，NVLink 5 的带宽再高也换不回被通信延迟占用的那几毫秒。因此单流单块前向应落在单卡单 SM 组内，编码器与解码器可以分居不同 SM 组以流水重叠：编码器产出第 t 块 token 的同时，解码器仍在消费第 t-1 块，两者通过片上或显存中的 token 环形缓冲交接。</p>\n<p>多流并发时，拓扑从“并行”转为“拼接”。设并发流数为 N，块长为 B，调度器在每个块边界把 N 条流的当前块在批维上拼成一个小批，一次前向同时推进所有流。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{for each block step } t:\\quad X_t = \\text{concat}(x_t^{(1)},\\dots,x_t^{(N)}),\\quad Y_t = f(X_t, S_{t-1}),\\quad S_t = g(X_t, S_{t-1})$$</div>\n<p>关键在于状态张量 <span class=\"formula\">$$S$$</span> 必须按流隔离：批维拼接的是输入，状态缓存则要按流索引寻址，否则就会出现流间串音与状态污染。这条约束直接决定拓扑形状——状态缓存要么按流分片存放在不同显存区域，要么在拼接前做一次按流的 gather/scatter，后者的访存代价随 N 与层数增长，是并发扩展时最先撞到的墙。</p>\n<p>代价侧写：单流拓扑的延迟下限由一次块前向加缓冲填充决定；多流拼接拓扑的吞吐随 N 上升，但每增加一路流就多一份状态缓存常驻显存，且拼接批的形状受最短块约束。具体例子：对话场景中一路流处于静音段、块内几乎无有效帧，拼接时若不做长度对齐就会拉低整批的有效计算密度，调度器应对此类流做块级跳过而非硬拼。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-29\">二十九 · 量化方案：计算路径低精度，状态缓存高精度</h3>\n<p>量化在分块推理里有一条硬分界：编码器/解码器的卷积与量化器查表可以走低精度，跨块状态缓存必须保持高精度。原因是状态缓存是跨块递推的载体，任何一次量化误差都会沿块序列累积，表现为块边界的能量跳变与周期性爆音——这正是失败模式里描述的那类伪影。误差累积的形态可以写成递推：</p>\n<div class=\"formula\">$$s_t = g(x_t, s_{t-1}) + \\epsilon_t,\\quad \\epsilon_t \\text{ 随块数累积}$$</div>\n<p>因此配方是“非对称量化”：权重与激活走 FP8 或 NVFP4，卷积 padding 缓冲、归一化统计（均值/方差或 running stats）、量化器历史缓冲保持 FP16/BF16 甚至 FP32。量化器查表本身是离散映射，低精度只影响码本索引的存储位宽，不影响查表结果的数值精度，这部分可以放心压。</p>\n<p>代价侧写：低精度计算路径降低单块前向的算力与寄存器压力，使更小的块长成为可能；但高精度状态缓存意味着这部分显存不能被压缩，容量与块长、层数成正比。具体例子：一个多层卷积编码器在 20ms 块下，每层需保留的 padding 长度等于感受野减一，层数越多、感受野越大，状态缓存越厚；若为省显存把状态缓存也压到 FP8，块边界伪影会在几十块之后显现，且无法通过重同步完全消除，只能靠定期用高精度重算状态来纠正。</p>\n<p>另一条量化细节：微缩放格式在编解码器上的收益集中在权重侧，激活侧的动态范围随块内内容波动（静音块与浊音块的能量差极大），逐块校准的缩放因子若复用上一块的值，会在块边界引入增益不连续。稳妥做法是每块独立计算激活缩放，代价是一次极小的归约开销，换来块边界无增益跳变。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-30\">三十 · KV 策略：卷积状态与量化器历史的容量模型</h3>\n<p>在分块编解码器里，“KV”概念上对应卷积状态与量化器历史缓冲，而不是注意力的键值对。容量模型可以直接写出：设层数 L、每层状态张量形状为通道数 C 乘以状态长度 R（感受野相关），则单流状态缓存字节数约为 <span class=\"formula\">$$\\text{Mem}_{\\text{state}} \\approx L \\cdot C \\cdot R \\cdot \\text{bytes}$$</span>，与总时长 T 无关。这是分块推理相对整段前向的核心优势：整段前向的激活显存随 T 线性膨胀，而分块后峰值只由 B 与状态缓存决定。</p>\n<p>策略上有三条具体规则。其一，状态缓存按层分配在固定显存池中，池大小按最大并发流数乘以单流容量预留，避免运行期碎片化分配带来的延迟抖动。其二，量化器历史缓冲只需保留最近若干个码本索引，长度由量化器的预测窗决定，不必与卷积状态等长，分开管理可以省下可观显存。其三，超长流必须定期状态重同步：每隔若干块用一段稍长的上下文重算一次状态，把累积的数值漂移清零，重同步的块会带来一次略高的延迟，调度器应把它安排在播放缓冲余量充足的时刻。</p>\n<p>代价侧写：状态缓存常驻显存意味着并发上限被显存容量直接约束，而不是被算力约束；重同步带来周期性的延迟尖峰，若与 SLO 的尾延迟指标冲突，需要把重同步周期拉长并配合重叠-相加的边界处理。具体例子：多流并发时若各流重同步时机不一致，拼接批内会出现某一路正在重算长上下文、其余路只算短块的情况，批形状被迫按最长路对齐，整批延迟被单路拖高——调度器应把重同步流临时移出拼接批单独执行。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-31\">三十一 · 调度参数：块长、批窗口与缓冲深度的联合整定</h3>\n<p>调度参数不是独立可调的旋钮，而是一组互相牵制的约束。块长 B 的下限由感受野与 GPU 利用率共同决定：B 小于感受野时，块边界需要额外重叠量才能避免感受野截断，重叠部分重复计算会拉低有效吞吐；B 过小还会让单块前向的固定开销占比上升，SM 占用率下降。B 的上限由首包 SLO 决定，因为首包延迟约等于一个块的前向时间加缓冲填充时间。典型取值落在 20–40ms，这个区间是延迟与质量之间的可行带。</p>\n<p>批窗口是第二个参数：调度器在每个块边界收集当前所有活跃流的块，形成一个批。窗口太短则批内流数不足、GPU 利用率低；窗口太长则等待凑批引入额外延迟，破坏首包预算。可行做法是以块边界为硬同步点，窗口长度等于一个块的时长，到点即发，不等待未就绪的流——未就绪流顺延到下一块，其状态缓存保持不变，不会污染其他流。</p>\n<p>缓冲深度是第三个参数：播放缓冲至少容纳一到两个块，用于吸收前向时间的抖动与重同步的延迟尖峰。缓冲越深，首包延迟中 <span class=\"formula\">$$t_{\\text{buf}}$$</span> 项越大，但抗抖动能力越强。整定顺序应是先定 B（受 SLO 与感受野夹逼），再定批窗口（等于 B），最后按实测的前向时间方差定缓冲深度。</p>\n<p>代价侧写：B 增大提升 GPU 利用率与吞吐，但首包延迟回升；批窗口增大提升批内流数，但凑批等待吃掉延迟预算；缓冲加深平滑抖动，但直接加在首包延迟上。具体例子：实时 TTS 单流场景取 B=20ms、批窗口一个块、缓冲一块，首包预算最紧；多流对话场景可把 B 提到 40ms 换取更高批密度，代价是首包延迟翻倍，需确认 SLO 仍可满足。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-32\">三十二 · 可复现的配置思路：从 SLO 倒推，按约束收敛</h3>\n<p>给出一个可复现的收敛流程，而不是一组拍脑袋的数值。第一步，从 SLO 取首包延迟上限，减去播放缓冲的预留，得到单块前向的时间预算；用这个预算去测编码器与解码器在候选块长下的实际前向时间，选出满足预算的最大 B——B 越大吞吐越好，所以在预算内取最大是正确方向。第二步，按 B 确定批窗口等于一个块时长，并据此估算单卡可容纳的并发流数：用显存容量除以单流状态缓存容量（层数 × 通道 × 状态长度 × 高精度字节数），得到硬上限，再与算力上限取小。</p>\n<p>第三步，量化方案按前述非对称原则落地：计算路径选 FP8 或 NVFP4，状态缓存锁定 FP16/BF16，激活缩放逐块独立计算。第四步，设定重同步周期：以块数为单位，周期长度取到使累积漂移在听感阈值以下，并把重同步流从拼接批中摘出单独执行，避免拖高整批延迟。第五步，用失败模式做验收清单：检查块边界是否有周期性爆音（状态缓存未正确延续）、检查 GPU 利用率是否因 B 过小而塌陷、检查多流拼接时是否有串音（状态未按流隔离）。</p>\n<p>这套流程的可复现性来自每一步都有明确的约束来源：SLO 给时间预算，感受野给块长下限，显存给并发上限，漂移给重同步周期。任何一步的取值变化都会沿链条传导，例如把 SLO 收紧会逼小 B，进而降低批密度、抬高单位吞吐成本，最终反映为需要更多卡或更低并发。工程判断落在最后一条：分块编解码器推理的容量规划，本质是在首包延迟、并发流数与状态缓存显存三者之间找一个可行点，而这个可行点的边界由块长 B 一个参数主导——调 B 就是调整个系统的形状。</p>\n<h3 id=\"alg-streaming-codec-chunk-sec-33\">三十三 · 显存账：为什么分块后峰值与时长解耦，却与层数线性绑定</h3>\n<p>整段编解码的显存峰值由激活张量主导，量级随总帧数 T 线性增长：每层卷积或注意力都要保留完整时间轴上的中间结果，峰值近似正比于 T×层数×通道数×精度字节。分块推理把这条曲线截断，激活只覆盖当前块 B 与有限历史状态，于是峰值表达式变为与 T 无关的常数项加状态项。真正需要算清的是状态项：跨块缓存不是一份，而是每层一份卷积 padding 缓冲、每层一份归一化统计（均值/方差或 running stat）、量化器侧一份码本历史与残差缓冲。设层数 L、块长 B、通道 C、状态精度 p 字节，状态显存约为</p>\n<div class=\"formula\">$$M_{\\text{state}} \\approx L \\cdot \\big(2R_{\\text{pad}} C + C\\big) \\cdot p + M_{\\text{quant}}(B)$$</div>\n<p>其中 R_pad 是每层需要保留的边界长度。这条式子给出一个工程判断：块长翻倍，激活翻倍而状态基本不变；层数翻倍，状态翻倍。因此深编码器（数十层卷积堆叠）在分块部署时，状态缓存会成为仅次于权重的第二大常驻开销，而它不随音频时长增长——这正是长音频流式场景能稳住显存的原因。代价的另一面是：多流并发时状态缓存按流数线性复制，N 路并发即 N 份 L 层缓冲。以 20ms 块、单流单块前向的负载配方为例，单流状态下这部分开销可忽略，但把并发拉到数十路做小批拼接时，状态缓存的隔离副本与批内张量拼装会成为显存增长的主因，而非激活。工程上应把状态缓存按流 ID 显式分池，避免因动态形状导致的分片碎片。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-34\">三十四 · 带宽账：块太小先把 L2 与 HBM 的有效带宽打下来</h3>\n<p>分块推理的带宽代价有两层。第一层是权重读取：每块前向都要把编码器与解码器权重从 HBM 过一遍，若块极小、批为 1，则算术强度极低，GPU 处于权重带宽受限区，SM 的 tensor core 大量空转。第二层是状态读写：每块开始要读入 s_{t-1}、每块结束要写回 s_t，这部分流量与块长成反比——块越短，单位音频时间内的状态往返次数越多。设单块前向时间 t_blk、状态字节 M_state、权重字节 M_w，则处理一秒音频所需的有效带宽近似为</p>\n<div class=\"formula\">$$\\text{BW}_{\\text{eff}} \\approx \\frac{1}{B}\\Big(M_w + 2M_{\\text{state}} + M_{\\text{act}}(B)\\Big)$$</div>\n<p>这条式子解释了可用事实中“块太小会降低 GPU 利用率”的物理根源：B 从 40ms 降到 20ms，状态往返频次翻倍，而权重流量按块摊薄的收益被固定开销吃掉。Blackwell 上的实际缓解手段是把多流按块拼成小批，让一次权重读取服务 N 条流，把 M_w 摊到 N 倍的有效工作上；同时用 TMEM 与片上共享内存承载状态缓存的热点层，减少每块的状态 HBM 往返。代价是批拼接引入调度抖动：不同流的块到达时刻不齐，拼批等待会直接加到首包延迟上，因此拼批窗口必须显著小于块长，否则低延迟 SLO 被吞吐优化反噬。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-35\">三十五 · 通信账：多流与多卡时，状态同步比 token 同步更贵</h3>\n<p>单卡单流的分块推理没有集合通信，但一旦走向多流服务或多卡并行，通信代价的结构就变了。分离式部署中编码器与解码器可能落在不同进程甚至不同节点，块级流水要求每个块边界做一次 token 流交接；若解码器侧还要拿回状态做重同步，则交接内容从离散 token 扩展到高精度状态张量。token 流是小消息、高频次，走 NVLink 5 或 NIXL 的零拷贝路径时延迟可控；状态张量是大消息、同样高频次，其字节量按第一节的 M_state 计，一旦跨节点就受链路带宽约束。设每块交接的状态字节 S、链路有效带宽 W_link、每块音频时长 B，则通信占用的时间比例为</p>\n<div class=\"formula\">$$\\rho_{\\text{comm}} \\approx \\frac{S}{W_{\\text{link}} \\cdot B}$$</div>\n<p>B 越小，ρ 越大。20ms 块配跨节点状态同步是危险的组合：块级周期短到通信延迟与内核启动开销无法被隐藏。工程判断是——状态缓存尽量与产生它的层同卡同进程，跨卡只传离散 token 与必要的量化后统计量；确需跨节点时把块长放宽到 40ms 档，用更大的 B 摊薄 ρ。多流并发下还有第三种通信代价：流间状态隔离若靠拷贝实现，会在批拼接时产生额外的设备内搬运，这部分走的是 HBM 而非 NVLink，容易被误计入计算时间。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-36\">三十六 · 功耗与利用率：低批小块是最差的能效区间</h3>\n<p>分块推理的功耗特征与吞吐特征同源。批为 1、块为 20ms 时，SM 占用率低、tensor core 空闲、HBM 频繁唤醒做小事务读写，整卡处于“高频低效”状态：功耗不低，但每焦耳完成的音频秒数很差。这与大批整段推理形成鲜明对比——后者算术强度高、能效好，但首包延迟不可接受。Blackwell 的功耗管理给了两条可操作的杠杆：一是用时钟门控与低占用核的降频策略，让等待拼批的空窗期不吃满功耗；二是把状态缓存的读写集中到少数热点层，减少全卡 HBM 唤醒次数。代价是降频会拉长单块前向时间，直接顶到首包 SLO 上，因此能效优化与延迟优化在分块场景里是硬冲突，必须按 SLO 优先级排序：首包延迟是硬约束，能效是软目标。可用事实给出的块长区间 20–40ms 正是这条冲突曲线的可行段——低于 20ms 能效崩，高于 40ms 首包延迟回升。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-37\">三十七 · 尾延迟：规模上去以后，先崩的是拼批等待与状态重同步</h3>\n<p>平均首包延迟由 L_first = t_enc(B) + t_dec(B) + t_buf 决定，但生产环境的 SLO 看的是 P99。分块推理的尾延迟有三个独立来源，规模上去后暴露顺序不同。第一是拼批等待：多流按块拼小批时，最早到达的流要等最晚的流，等待时间在流数增多、到达间隔方差增大时迅速拉长尾部，这是最先崩的一环，因为它的分布直接继承请求到达过程的尾部。第二是状态重同步：可用事实明确指出超长流需定期重同步以防漂移，重同步那一块要做重叠-相加或全状态重建，其前向时间显著高于普通块，于是每 N 块出现一次周期性尖峰，恰好落在 P99 上。第三是显存分片与状态池碎片：并发路数上升后，动态形状的状态缓存分配可能触发同步与重试，表现为偶发的长尾块。</p>\n<p>三者的排序有工程意义：拼批等待靠缩短拼批窗口与按流优先级调度缓解，代价是吞吐下降；重同步尖峰靠把重同步摊到低负载时段或与块边界错峰缓解，代价是实现复杂度；显存碎片靠预分配固定形状的状态池消除，代价是并发上限被静态锁定。可用事实里的失败模式——多流状态未隔离导致串音与污染——在规模上去后往往以尾延迟而非错误的形式先显现：污染触发重同步，重同步拉长尾。因此监控应把“每流重同步频次”与“拼批等待时长”作为一等指标，而不是只看平均首包。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-38\">三十八 · 规模上限的判定顺序与一个具体例子</h3>\n<p>把五条账合起来，规模上去后的崩溃顺序可以给出判定：单流低延迟场景先撞块长下限（感受野与利用率），多流并发先撞拼批等待尾延迟，跨节点分离式部署先撞状态同步的 ρ_comm，深编码器长音频先撞状态缓存的常驻显存，而功耗墙通常在以上四项都放宽后才成为约束。以一个 20ms 块、单卡、数十路并发的实时 TTS 服务为例：单流时首包约等于一块前向加缓冲填充，显存与带宽都宽裕；并发升到数十路后，状态缓存按流复制占用常驻显存，拼批窗口内的等待把 P99 首包推高，此时若再把编码器与解码器拆到两卡，20ms 块下的状态交接让 ρ_comm 逼近临界，尾延迟进一步恶化。正确的处置不是加卡，而是把块长放宽到 40ms 档、把状态缓存锁在同卡、用固定形状状态池换掉动态分配——这三步分别打掉 ρ_comm、显存碎片与部分拼批方差，代价是单块前向时间变长、并发上限被静态锁定。判断的落点是：分块推理的规模上限不由算力决定，而由“块级周期 B 能否覆盖状态往返、拼批等待与通信开销”决定，B 一旦被首包 SLO 压死，剩下的优化空间就只在状态本地化与调度错峰上。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-39\">三十九 · 规模上去以后，先崩的是状态缓存与块边界，不是显存</h3>\n<p>把块长压到 20–40ms 之后，单流路径上最先被吃满的不是 HBM 容量，而是每块前向的固定开销与状态缓存的访问带宽。块前向的计算量近似正比于 B·R（块长乘感受野），而每块必须把上一块的卷积 padding、归一化统计、量化器历史整块读入再写回，这部分搬运量与层数、通道数成正比、与 B 无关。于是当 B 取 20ms 时，状态读写占总字节的比例随层数线性上升，GPU 的有效算力利用率被这些常数项摊薄：块越小，单位 token 摊到的状态搬运越多，SM 上真正做 MMA 的时间片越短，tcgen05 的发射节奏被频繁的 kernel 边界切断。单流低延迟场景下这不是吞吐问题，而是尾延迟问题——每个块的前向时间方差被状态同步点放大。</p>\n<p>多流并发时失效点转移。按块做小批拼接（batch 通常为 1 或小批多流）意味着不同流的块在同一 kernel 里对齐发射，若各流状态缓存未隔离或重同步时机不一致，就会出现流间串音与状态污染，表现为某一路的块边界咔哒声串到另一路。更隐蔽的是批内块长不齐：短块先到、长块后到，调度器若按最慢块收批，尾延迟由批内最长块决定，公式上首包延迟从单块的 $$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}}$$ 退化为 $$L_{\\text{first}}^{\\text{batch}} = \\max_i\\big(t_{\\text{enc}}(B_i) + t_{\\text{dec}}(B_i)\\big) + t_{\\text{buf}}$$，多流收益被最慢流吃掉。</p>\n<p>带宽与功耗的账要分开算。状态缓存保持高精度以避免跨块误差累积，量化只压在编码器/解码器卷积与量化器查表上，于是每块前向的访存里高精度状态占了大头；在 Blackwell 上这体现为 L2 与 HBM 之间的往返次数随层数上升，而不是随总时长上升——长音频不涨显存峰值，但持续流的稳态带宽占用是常数级的，功耗也稳定在块前向的峰值附近，缺少整段推理那种长 kernel 的能效平滑。超长流还需定期状态重同步以防漂移，重同步本身是一次额外的前向对齐，构成周期性尾延迟尖峰。</p>\n<p>工程判断落在块长与重同步周期的联合整定上：B 的下限由感受野覆盖与 GPU 利用率共同约束，上限由首包 SLO 约束，典型 20–40ms；重同步周期则要短于状态漂移累积到可听阈值的时长。真正先崩的顺序是：多流状态隔离 → 块边界伪影 → 批内尾延迟 → 稳态带宽，显存峰值反而最后才成为约束。</p>\n<h3 id=\"alg-streaming-codec-chunk-sec-40\">四十 · 精度漂移：状态缓存是唯一不能降精度的东西</h3>\n<p>分块推理的数值风险不在单块前向，而在跨块状态缓存的累积。卷积 padding 缓冲与归一化统计量（均值/方差、LayerNorm 的 running stat）在块间反复读写，每一次低精度舍入都会进入下一块的输入，误差沿时间轴单调累积而非随机抵消。工程上必须把状态缓存与计算精度分层：编码器/解码器的权重与激活可走 NVFP4/FP8 的 tcgen05 路径，量化器查表可走低比特索引，但 <code>s_t</code> 本身保持 FP16/BF16 甚至 FP32。判据是块边界能量跳变：对相邻块拼接点做 1–2 帧的短时能量差与过零率比对，若出现每块一次的周期性尖峰，即为状态舍入漂移的典型指纹。</p>\n<p>诊断公式化：设第 t 块拼接处残差 <code>e_t = |E(y_t[0:k]) − E(y_{t-1}[-k:])|</code>，k 为重叠帧数。正常流 <code>e_t</code> 应围绕一个与信号包络相关的基线波动；一旦 <code>e_t</code> 的均值随块序号线性上升，说明状态缓存精度不足或归一化统计未正确延续。回滚路径是精度分层开关：把状态缓存单独提升到高精度重跑同一段音频，若 <code>e_t</code> 回落则确认是数值问题而非状态逻辑问题。代价上，状态缓存高精度只增加与块长×层数成正比的常驻显存，不随总时长增长，对首包延迟无影响——这是分块推理相对整段前向的结构性优势，应当毫不犹豫地用掉。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-41\">四十一 · OOM 的三个来源与隔离手法</h3>\n<p>分块推理的显存峰值理论上只与块大小和状态缓存有关，但工程中 OOM 仍会出现，来源有三类。第一类是批拼接：多流并发时把 N 条流的当前块拼成一个小批，激活显存按 N 线性放大，而状态缓存是每流独立的 N 份，二者叠加后峰值远超单流预算。第二类是播放缓冲与解码输出的双缓冲：波形块写入播放队列时若未做背压，队列会随消费端抖动而膨胀。第三类是框架侧的 KV 概念对应物——卷积状态与量化器历史缓冲按层数×块长分配，若按最大块长预分配而实际块长更小，则存在静态浪费。</p>\n<p>隔离手法按优先级排序：先给状态缓存设硬上限并按流做池化分配，池满时拒绝新流而不是让批无限增长；再给播放缓冲设水位线，超过高水位即暂停该流的解码前向（背压而非丢弃）；最后把批拼接的 N 做成运行时可调的旋钮，由调度器根据当前显存余量决定，而不是编译期常量。监控指标是 <code>peak_mem / budget</code> 的滑动最大值与状态缓存池占用率，两者同时逼近上限时优先降 N。注意 OOM 在 Blackwell 上常表现为异步分配失败而非即时异常，因此必须在每个块前向之后插入显存水位采样点，否则错误会延迟到下一个流才暴露。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-42\">四十二 · 批抖动与路由不均：小批多流的调度病理</h3>\n<p>分块推理的负载配方是小批多流，块长 20–40ms，这意味着调度器每 20ms 就要做一次批组装决策。批抖动来自流到达时间的相位差：若各流的块边界不对齐，批内会出现“等最慢流”的空转，GPU 利用率随流数增加反而下降。路由不均则出现在多卡或多实例部署下，按流哈希路由会把长流集中到同一实例，造成该实例状态缓存池先满、尾延迟抬升，而其他实例空闲。</p>\n<p>机制上采用块相位对齐加最短队列路由：调度器维护每条流的下一块到期时刻，按到期时刻排序组装批，允许微小的时间窗聚合（窗宽小于块长的十分之一量级），把相位接近的流合并；路由侧不看流 ID 哈希，而看目标实例的“状态缓存池余量 + 当前批占用”复合分数。伪代码思路：<code>score(i) = α·(1 − pool_used_i) + β·(1 − batch_occ_i)</code>，取最大者。代价是路由决策本身引入一次跨实例查询的往返，若走 NVLink 5 域内的 NIXL 元数据通道，这次查询可压到与一次块前向同量级以下；跨域则必须缓存路由表并做周期性刷新，否则路由开销会吃掉低延迟收益。判据是批内空转率与实例间池占用率的基尼系数，前者高说明相位未对齐，后者高说明路由偏斜。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-43\">四十三 · 尾延迟尖刺：状态重同步是尖刺的主要制造者</h3>\n<p>分块推理的 P99 尖刺几乎都来自状态重同步。正常路径下 <code>y_t = f(x_t, s_{t-1})</code> 是常数时间；一旦检测到状态未对齐（例如流被迁移、块被丢弃后重放、或重叠-相加校验失败），系统触发重同步：回退若干块、重建状态缓存、再重叠-相加拼接。这次重同步的代价是若干个块的前向时间加上状态重建，直接体现为一次数十毫秒到上百毫秒的延迟尖刺，且恰好落在最需要稳定的对话场景。</p>\n<p>控制手段是重同步预算化：把重同步限制在块边界且只允许回退固定窗口（如 2–3 块），并对每条流设重同步频率上限，超限则降级为静音填充加渐入而非硬切。监控上不能只看平均首包延迟，必须分位数采集并单独打点重同步事件：<code>P99 = quantile(latency, 0.99)</code> 与 <code>resync_rate</code> 联合观察，若 P99 抬升而 resync_rate 同步抬升，则根因确定。另一个尖刺来源是块太大导致首包延迟回升——块长上限受首包 SLO 约束，典型 20–40ms，超过则首包时间直接突破 SLO，这类尖刺是配置性的、可预测的，应在容量规划阶段就排除，而不是留到线上诊断。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-44\">四十四 · 监控面与回滚阶梯</h3>\n<p>监控面按三层组织。音频质量层：块边界能量跳变 <code>e_t</code>、周期性咔哒检测（对拼接点做频谱突变检测）、流间串音指标（多流隔离失效时表现为一条流的输出混入另一条流的能量包络）。系统层：首包延迟分位数、批内空转率、状态缓存池占用、重同步率、显存水位峰值。路由层：实例间池占用基尼系数、跨实例路由查询耗时。三层指标必须带流 ID 维度下钻，否则无法区分“全局劣化”与“单流污染”。</p>\n<p>回滚阶梯按代价从低到高：一级是精度分层开关，把状态缓存提到高精度；二级是块长上调一档（如从 20ms 到 40ms），以首包延迟换感受野有效性与拼接稳定性；三级是关闭小批拼接退回批大小为 1 的单流路径，牺牲吞吐保延迟与隔离；四级是路由表冻结并做流迁移，把污染流隔离到独立实例。每一级都必须可在不重启进程的前提下热切换，因为分块推理的状态缓存是常驻的，重启意味着所有在途流的首包重新计时。回滚判据用联合条件而非单指标：只有当 <code>e_t</code> 与 <code>resync_rate</code> 同时越限才触发二级以上回滚，避免因单次尖刺误触发全局降级。</p>\n<p>工程判断上，分块推理的失败模式有一个共同结构：它们都发生在块边界，而块边界正是状态缓存交接的唯一时刻。因此诊断的第一动作永远是抓取边界前后的状态快照与输入块，比对 <code>s_{t-1}</code> 的延续是否与 <code>g(x_t, s_{t-1})</code> 的写入一致——这条不变量一旦被破坏，后续所有指标都会以周期性伪影的形式报警，而修复点始终落在那一次交接上。</p>\n\n\n<h3 id=\"alg-streaming-codec-chunk-sec-45\">四十五 · 块边界与状态缓存：分块推理的失效面与可回滚监控</h3>\n<p>分块推理的稳定性完全押在跨块状态缓存的正确延续上，因此失败模式几乎都围绕“状态是否对齐”展开。设块长 B、感受野 R，第 t 块输出依赖上一块缓存状态：<div class=\"formula\">$$y_t = f(x_t, s_{t-1}),\\quad s_t = g(x_t, s_{t-1})$$</div>一旦卷积 padding 或归一化统计未按层、按通道精确延续，块边界就会出现周期性爆音与能量跳变，听感上是每块一次的咔哒声，且频率与块长严格对应——这正是诊断的第一抓手：若伪影周期等于 20ms 或所设块长，问题几乎必然在状态缓存而非模型权重。量化器历史缓冲同理，RVQ 层间查表若丢失上一块的残留状态，token 序列在边界处会突变，解码波形出现短促的能量台阶。工程上应把“每块输出的边界能量差”做成常驻指标，与块长周期做相关分析，而不是等人工听测发现。</p>\n<p>第二类失效来自块长与批的耦合。块长压到 20ms 以下以追求更低首包延迟，会让 GPU 利用率与感受野有效性同时下降：单块前向的矩阵规模太小，kernel 启动与状态读写开销占比上升，吞吐恶化；同时感受野无法覆盖有效上下文，音质劣化。反过来块长超过 40ms，首包延迟按 <div class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}}$$</div>回升，直接击穿 SLO。多流并发时按块拼接小批，若各流状态缓存未隔离，或重同步时机不一致，会出现流间串音与状态污染——表现为某一路音频混入另一路的音色残留，且只在并发数上升时出现。诊断方法是给每条流的状态缓存打独立标识并在批内做隔离校验，同时监控批内各流的边界能量差分布，单流正常而批内方差骤增即为污染信号。</p>\n<p>监控与回滚要按代价分层。状态缓存容量与块长、层数成正比、不随总时长增长，因此显存侧的主要风险不是长音频而是多流并发下的缓存副本数：每增加一条流就多一份卷积状态与量化器历史，OOM 往往在并发爬坡时突然出现而非渐进。批抖动则来自块到达时间的抖动——文本/声学模型产出块不均匀时，按块拼批会造成批大小在 1 与小批之间反复跳变，GPU 利用率与尾延迟同时恶化。尾延迟尖刺的典型来源是状态重同步：超长流需定期重同步以防漂移，重同步那一块的前向会额外读取更长历史，形成周期性尖刺。回滚策略应分级：先降并发上限与块长回到 20–40ms 的安全区，再关闭跨流拼批退回单流单块，最后回退到整段编解码兜底——后者首包延迟随总时长线性增长，只作为可用性保底而非性能路径。状态缓存保持高精度、仅对卷积与量化器查表做低精度，是避免跨块误差累积的底线，回滚时不应改动这一层。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>最可能根因</th><th>首要动作</th></tr></thead><tbody><tr><td>周期等于块长的咔哒声</td><td>padding/归一化统计未延续</td><td>校验逐层状态缓存对齐</td></tr><tr><td>并发上升即串音</td><td>流间状态未隔离</td><td>状态缓存按流打标并隔离</td></tr><tr><td>批大小反复跳变</td><td>块到达抖动</td><td>块缓冲对齐后再拼批</td></tr><tr><td>周期性尾延迟尖刺</td><td>定期状态重同步</td><td>错峰重同步、拉长重同步间隔</td></tr></tbody></table>\n<h3 id=\"alg-streaming-codec-chunk-sec-46\">四十六 · 同族谱系：四种流式解码的切分维度</h3>\n<p>把“流式编解码器分块推理”放回同族算法里看，它并不是唯一的切分方案，而是沿“时间轴切块 + 跨块状态延续”这一维度做的。同族算法至少还有三条正交路线：残差矢量量化流式解码沿“码本层轴”切分，逐层查表、逐层叠加，瓶颈在层间查表带宽与码本驻留；自回归码本 LM 投机解码沿“token 轴”做草稿-校验，瓶颈在接受率与校验批的并行度；非自回归时长预测批推理沿“样本轴”并行，把整句一次性铺开，瓶颈在批内对齐与显存占用。四者的切分维度不同，代价曲线就完全不同：时间轴切块把首包延迟压到常数，但引入状态缓存复杂度；层轴切分把单帧计算摊薄，但每帧仍需走完全部 RVQ 层；token 轴投机把解码步数减少，但需要额外的草稿模型与校验开销；样本轴并行把吞吐拉满，却对首包延迟毫无帮助。</p>\n<p>判断一个负载该落在哪条轴上，先看它的 SLO 主指标。实时 TTS 与语音对话的主指标是首包延迟，公式 $$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$ 直接说明：只要块长 B 远小于总时长，首包就与总时长解耦。反过来，离线批量转写的主指标是吞吐，样本轴并行更划算。这就是同族算法选择的第一个分水岭——SLO 是延迟型还是吞吐型。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-47\">四十七 · 决策表：按负载形态落到具体算法</h3>\n<p>下表把常见负载形态与同族算法的匹配关系固定下来，列出的判据都是可观测的工程量，不是定性描述。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主 SLO</th><th>首选算法</th><th>关键判据</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>实时 TTS / 语音对话下行</td><td>首包延迟</td><td>分块推理（本算法）</td><td>块长 20–40ms，单流或小批多流</td><td>状态缓存复杂度、块边界伪影</td></tr>\n<tr><td>长音频离线转写</td><td>吞吐 / 显存峰值</td><td>整段或大块批推理</td><td>总时长长、无首包约束</td><td>显存随长度增长</td></tr>\n<tr><td>RVQ 码本流式合成</td><td>层间查表带宽</td><td>RVQ 分层渐进解码</td><td>码本层数多、层间依赖强</td><td>逐层串行、层间同步</td></tr>\n<tr><td>码本 LM 解码慢</td><td>解码步数</td><td>码本 LM 投机解码</td><td>草稿接受率高、校验批可并行</td><td>草稿模型显存与校验开销</td></tr>\n<tr><td>整句并行合成</td><td>吞吐</td><td>非自回归时长预测批推理</td><td>时长可预测、批内可对齐</td><td>批内对齐与显存占用</td></tr>\n<tr><td>多流并发服务</td><td>尾延迟 / 隔离性</td><td>分块 + 小批拼接</td><td>各流状态缓存隔离、重同步时机一致</td><td>流间串音与状态污染风险</td></tr>\n</tbody></table>\n<p>表里最容易被误判的是第一行与第五行的边界：一个系统如果既要求首包低延迟又要求高吞吐，就不能简单二选一，而要把分块推理作为延迟路径、把批推理作为吞吐路径，在调度层按请求的 SLO 标签分流。分流判据是请求是否携带“首包截止时间”，而不是请求长度——长请求同样可能是实时对话的一部分。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-48\">四十八 · 适用条件：块长 B 与感受野 R 的约束</h3>\n<p>分块推理能不能用，取决于三个不等式是否同时成立。第一是感受野约束：第 t 块输出依赖第 t-1 块缓存状态与当前块输入，即 $$y_t = f(x_t, s_{t-1}),\\ s_t = g(x_t, s_{t-1})$$，只有当块长 B 与感受野 R 的边界重叠量足够时，拼接处才不发生感受野截断。B 小于 R 而不做重叠，块边界就是硬截断，输出会出现周期性能量跳变。第二是利用率约束：B 太小，单块前向的矩阵规模不足以填满 GPU，SM 占用率下降，吞吐随 B 减小而恶化。第三是 SLO 约束：B 太大，首包延迟回升，因为首包必须等满一个块的前向加播放缓冲填充。</p>\n<p>三个约束把 B 夹在 20–40ms 这个区间：下限由感受野与利用率共同抬升，上限由首包 SLO 压低。工程上判断一个模型能否落入该区间，看它的感受野折算成时间是多少——卷积堆叠深的编解码器感受野可能超过一个块，此时必须靠重叠-相加把边界补上，代价是每块多做一次重叠区的冗余前向。若模型感受野折算后远大于 40ms，分块推理的块边界处理成本会吞掉延迟收益，此时应优先考虑层轴切分或整段批推理，而不是硬调小 B。</p>\n<div class=\"formula\">$$B_{\\min} = \\max(R_{\\text{eff}},\\ B_{\\text{util}}),\\quad B_{\\max} = B_{\\text{SLO}} - t_{\\text{buf}}$$</div>\n<p>这里 $$R_{\\text{eff}}$$ 是感受野折算到时间的有效长度，$$B_{\\text{util}}$$ 是维持 GPU 利用率所需的最小块，$$B_{\\text{SLO}}$$ 是首包截止时间允许的最大块。区间为空，说明该模型不适合分块推理，这是选型时最先要算的一步。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-49\">四十九 · 与层轴、token 轴算法的组合与排斥</h3>\n<p>分块推理与 RVQ 分层渐进解码可以叠加：块内先解最粗一层码本立即出声，细层随后补齐，这样首包延迟由“一个块 + 一层码本”决定，而不是“一个块 + 全部层”。叠加的代价是层间查表带宽与块内串行度同时上升，需要评估块内层数是否把单块前向时间推过 SLO。反过来，分块推理与码本 LM 投机解码叠加要谨慎：投机解码的草稿-校验本身有步数开销，若块长已经很小，单块内可投机的步数有限，接受率带来的收益被块边界开销抵消，此时应把投机放在块间而非块内。</p>\n<p>与非自回归时长预测批推理则是排斥关系：后者要求整句时长已知、整批对齐，天然与“按块到达、边到边算”的流式形态冲突。一个系统若同时部署这两条路径，调度层必须按请求是否可预知全长来分流，不能在同一请求上混用。多流并发时，分块推理按块做小批拼接，各流状态缓存必须隔离，重同步时机必须一致，否则出现流间串音与状态污染——这是分块路径在多流场景下最典型的系统代价，表现为尾延迟抖动而非平均吞吐下降。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-50\">五十 · 选型的工程判断：三个可测量</h3>\n<p>落到实操，选型不靠算法名字的直觉，靠三个可测量。其一是首包延迟分解：把 $$L_{\\text{first}}$$ 拆成编码块时间、解码块时间、缓冲填充三部分，看哪一项占主导；若编码块占主导，说明块长或编码器感受野是瓶颈，调 B 或换层轴切分；若缓冲占主导，说明块长已不是问题，该看播放侧的填充策略。其二是显存峰值随长度的斜率：整段推理的峰值随总时长线性上升，分块推理的峰值只与块大小和状态缓存成正比，斜率接近零即为分块生效的直接证据。其三是块边界伪影的周期性：若听感上出现每块一次的咔哒声，说明状态缓存未正确延续卷积 padding 或归一化统计，这不是块长问题，而是状态实现问题，调 B 无效。</p>\n<p>三个可测量里，斜率与周期性是分块路径独有的诊断量，首包分解则是同族算法共用的。把三者放在同一张监控面板上，就能在不停机的情况下判断当前负载是否还落在分块推理的适用区间内：斜率抬升说明有请求走了整段路径，周期性伪影说明状态缓存实现退化，首包分解偏移说明块长该重调。选型的最终判断不是“哪个算法更好”，而是“当前负载的三个可测量是否仍满足分块推理的适用条件”，不满足就切到相邻算法，满足就守住块长与状态缓存这两条不变量。</p>\n\n<h3 id=\"alg-streaming-codec-chunk-sec-51\">五十一 · 块切分与状态延续的决策边界：何时该用分块、何时退回整段或 RVQ 层间流式</h3>\n<p>把分块推理放进同族算法的坐标系里，第一个分水岭是“延迟由谁决定”。整段编解码的延迟是 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B) + t_{\\text{dec}}(B) + t_{\\text{buf}},\\quad B \\ll T_{\\text{total}}$$</span> 中 B 被替换成 T 的退化情形：首包必须等全部帧进入感受野，于是首包延迟随总时长线性增长，显存峰值随音频长度膨胀。分块方案把 B 压到 20–40ms，首包只依赖当前块与有限历史状态，代价是引入状态缓存 s<sub>t−1</sub> 与状态更新 s<sub>t</sub>=g(x<sub>t</sub>,s<sub>t−1</sub>)。因此选型的第一条判据不是“哪个更快”，而是 SLO 是否以首包延迟为主指标：实时对话与流式 TTS 必须选分块；离线批量转写、有声书整段合成这类吞吐优先、首包不敏感的负载，整段一次前向反而省掉状态管理与重同步开销，GPU 利用率也更高。第二条判据是感受野与块长的关系：只有当块边界重叠量足以覆盖卷积/Transformer 感受野 R 时，拼接处才无截断，B 的下限由 R 与 GPU 利用率共同钉住，上限由首包 SLO 钉住。</p>\n<p>与残差矢量量化流式解码的分工要一句话说清：后者聚焦 RVQ 层间查表带宽与码本驻留，本方案聚焦感受野的块切分与跨块状态延续，两者可以叠加但不可互相替代——RVQ 流式解决“层间怎么边查边出”，分块解决“时间轴上怎么边算边出”。真正的失效条件集中在状态一侧：卷积 padding 或归一化统计未正确延续，块边界会出现周期性爆音与能量跳变，听感上是每块一次的咔哒声；多流并发按块拼小批时，若各流状态缓存未隔离或重同步时机不一致，会出现流间串音与状态污染。这两类故障不会因加大批或换框架自动消失，必须在实现层把状态缓存做成按流 ID 索引的独立结构，并在块边界显式触发重叠-相加或状态重同步。超长流还需定期重同步以防数值漂移，因为状态缓存保持高精度、量化只作用于卷积与量化器查表，误差仍会沿块链累积。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>块长 B</th><th>批形态</th><th>首选方案</th><th>主要代价</th></tr></thead><tbody><tr><td>实时语音对话 / 流式 TTS</td><td>20–40ms</td><td>单流或小批多流</td><td>分块 + 跨块状态缓存</td><td>状态管理复杂度、块边界伪影风险</td></tr><tr><td>离线整段合成 / 批量转写</td><td>整段 T</td><td>大批</td><td>整段一次前向</td><td>首包延迟与显存随长度增长</td></tr><tr><td>码本受限、层间带宽瓶颈</td><td>按 RVQ 层</td><td>单流</td><td>RVQ 层间流式解码</td><td>层间查表带宽</td></tr><tr><td>超长流、状态漂移敏感</td><td>20–40ms + 周期重同步</td><td>单流</td><td>分块 + 定期状态重同步</td><td>重同步引入的瞬时质量抖动</td></tr></tbody></table>\n<p>决策表背后是一条工程判断：分块推理的显存峰值只与块大小和状态缓存有关，状态缓存容量与块长、层数成正比而不随总时长增长，这正是它能在单卡上支撑长对话的结构性优势；但块太小会让 GPU 利用率与感受野有效性同时下降，音质与吞吐一起恶化，块太大则首包延迟回升。调 B 的本质是在“首包 SLO”和“单块前向的算术强度”之间取交点，而不是追求某个固定值。当负载从单流对话切到多流并发，按块拼小批能摊薄权重读取带宽，但必须保证每流状态隔离与重同步时机一致，否则串音比延迟更早击穿 SLO。若首包预算已被声学模型占满、编解码器只剩极小份额，则应优先压缩块内前向（低精度卷积、量化器查表）而非继续缩小 B，因为后者会同时损失感受野覆盖与 GPU 利用率，属于用质量换一个已经够用的延迟指标。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 流式编解码器与首包延迟</td></tr><tr><td>解决什么</td><td>神经音频编解码器（如 SoundStream/AudioDec）若整段编码解码，首包延迟高且显存峰值大，无法满足实时 …</td></tr><tr><td>一句话机制</td><td>将编解码器卷积/Transformer 感受野按固定帧块切分，维护跨块因果状态缓存，逐块编码与解码，使首包只依赖当前块…</td></tr><tr><td>代价与失效</td><td>跨块状态缓存增加实现复杂度，状态错位会导致块边界伪影；块太小会降低 GPU 利用率与编解码器感受野有效性，需在延迟与质量间调 B</td></tr><tr><td>后继</td><td>双流全双工语音对话推理</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-streaming-codec-chunk · 共 8 个片段</p>\n";break;}}})();
